/* SkillSetu polished SIH prototype
   Works in BOTH modes:
   1) double-click public/index.html (file://) using localStorage demo data
   2) npm start -> http://localhost:3000 using the existing backend for seed data
*/
const API = location.protocol === 'file:' ? null : '/api';
const STORE='skillsetu_demo_v3';
let state = JSON.parse(localStorage.getItem(STORE) || 'null') || {
  account:null, profiles:{}, certificates:[], selectedRole:'student', currentPage:'dashboard', selectedStudent:'s1', created:false
};
const seedSkills=[
  {id:'python',name:'Python',cat:'Software'},{id:'react',name:'React.js',cat:'Software'},{id:'html',name:'HTML & CSS',cat:'Software'},{id:'js',name:'JavaScript',cat:'Software'},{id:'java',name:'Java',cat:'Software'},{id:'sql',name:'SQL',cat:'Software'},{id:'data-analysis',name:'Data Analysis',cat:'Research'},{id:'uiux',name:'UI/UX Design',cat:'Design'},{id:'communication',name:'Communication',cat:'Soft Skill'},{id:'teamwork',name:'Teamwork',cat:'Soft Skill'},{id:'problem-solving',name:'Problem Solving',cat:'Soft Skill'},{id:'ayur-diag',name:'Ayurvedic Diagnosis',cat:'Clinical'},{id:'panchakarma',name:'Panchakarma Therapy',cat:'Clinical'},{id:'patient-comm',name:'Patient Communication',cat:'Communication'}
];
const demoJobs=[
 {id:'d1',title:'Frontend Developer Intern',org:'TechNova Solutions',loc:'Remote · 3 months',req:['react','javascript','html'],score:92},
 {id:'d2',title:'Data Analyst Intern',org:'DataMind Analytics',loc:'Hybrid · 2 months',req:['python','data-analysis','sql'],score:78},
 {id:'d3',title:'UI/UX Design Intern',org:'PixelCraft Studio',loc:'Remote · 3 months',req:['uiux','communication'],score:84},
 {id:'d4',title:'Full Stack Developer',org:'BuildTech Pvt Ltd',loc:'Coimbatore · 6 months',req:['react','node','sql'],score:68}
];
let serverSkills=[],serverStudents=[],serverJobs=[];

function save(){localStorage.setItem(STORE,JSON.stringify(state))}
function esc(s){return String(s??'').replace(/[&<>'"]/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[m]))}
function initials(name){return (name||'User').split(' ').filter(Boolean).slice(0,2).map(x=>x[0]).join('').toUpperCase()}
function toast(msg){const t=document.getElementById('toast');t.textContent=msg;t.classList.add('show');clearTimeout(window._toast);window._toast=setTimeout(()=>t.classList.remove('show'),2600)}
function showModal(html){document.getElementById('modalCard').innerHTML=html;document.getElementById('modalBackdrop').classList.remove('hidden')}
function closeModal(){document.getElementById('modalBackdrop').classList.add('hidden')}
document.getElementById('modalBackdrop').addEventListener('click',e=>{if(e.target.id==='modalBackdrop')closeModal()});

async function getJSON(url,opts){
  if(!API) throw new Error('offline');
  const r=await fetch(url,opts); if(!r.ok) throw new Error('request'); return r.json();
}
async function bootData(){
  if(API){try{serverSkills=await getJSON(`${API}/skills`);serverStudents=await getJSON(`${API}/students`);serverJobs=await getJSON(`${API}/jobs`)}catch(e){}}
}
function skills(){return serverSkills.length?serverSkills:seedSkills}
function jobs(){return serverJobs.length?serverJobs:demoJobs}

/* ---------------- AUTH ---------------- */
function openLogin(role='student'){document.getElementById('registerScreen').classList.add('hidden');document.getElementById('authScreen').classList.remove('hidden');document.getElementById('appShell').classList.add('hidden');setLoginRole(role)}
function setLoginRole(role){state.selectedRole=role;document.querySelectorAll('#loginRoleTabs .role-tab').forEach(b=>b.classList.toggle('active',b.dataset.role===role))}
document.querySelectorAll('#loginRoleTabs .role-tab').forEach(b=>b.addEventListener('click',()=>setLoginRole(b.dataset.role)));
document.getElementById('existingLoginBtn').onclick=()=>document.getElementById('loginCard').scrollIntoView({behavior:'smooth'});
document.getElementById('registerBtn').onclick=()=>startRegistration();
document.getElementById('backToLogin').onclick=()=>openLogin();
document.getElementById('forgotLink').onclick=e=>{e.preventDefault();toast('For this prototype, use any demo password to continue.')} ;
document.getElementById('loginForm').addEventListener('submit',e=>{e.preventDefault();const email=document.getElementById('loginEmail').value.trim();const role=state.selectedRole;const existing=Object.values(state.profiles).find(p=>p.email===email&&p.role===role);state.account=existing||{id:'demo-'+Date.now(),email,role,name:role==='student'?'Vasanth Kumar':role==='college'?'Saranathan College of Engineering':'TechCorp Pvt Ltd'};if(!state.profiles[state.account.id])state.profiles[state.account.id]=state.account;save();launchApp()});

let regStep=1, regData={role:'student',name:'',email:'',password:'',college:'',department:'',phone:'',skills:[],certificates:[],orgType:'',website:'',location:'',description:'',contactPerson:''};
function startRegistration(){regStep=1;regData={role:'student',name:'',email:'',password:'',college:'',department:'',phone:'',skills:[],certificates:[],orgType:'',website:'',location:'',description:'',contactPerson:''};document.getElementById('authScreen').classList.add('hidden');document.getElementById('registerScreen').classList.remove('hidden');renderRegistration()}
function renderProgress(){return `<div class="progress-head"><div><span class="step ${regStep>=1?'active':''}">1</span><b>Choose role</b></div><i></i><div><span class="step ${regStep>=2?'active':''}">2</span><b>Create account</b></div><i></i><div><span class="step ${regStep>=3?'active':''}">3</span><b>Complete profile</b></div></div>`}
function renderRegistration(){const c=document.getElementById('registerContent');c.innerHTML=renderProgress()+ (regStep===1?roleStep():regStep===2?accountStep():profileStep());}
function roleStep(){return `<div class="reg-panel"><h1>Choose your role</h1><p>Tell us who you are so SkillSetu can create the right workspace for you.</p><div class="role-choice">
${[['student','🎓','Student','Build your verified skill passport, find opportunities and grow your career.'],['college','🏛','College','Manage students, track skill gaps and collaborate with industry.'],['company','💼','Company','Post opportunities, discover talent and build your team.']].map(x=>`<div class="role-card ${x[0]} ${regData.role===x[0]?'selected':''}" data-reg-role="${x[0]}"><div class="role-icon">${x[1]}</div><h3>${x[2]}</h3><p>${x[3]}</p><button class="primary-btn">Continue →</button></div>`).join('')}</div></div>`}
function accountStep(){return `<div class="reg-panel"><h1>Create your account</h1><p>Use an email and password for your SkillSetu workspace.</p><div class="reg-form"><div class="field"><label>Full name / authorized representative<input id="rName" value="${esc(regData.name)}" placeholder="Enter your name"></label></div><div class="field"><label>Email address<input id="rEmail" type="email" value="${esc(regData.email)}" placeholder="you@example.com"></label></div><div class="field"><label>Password<input id="rPass" type="password" value="${esc(regData.password)}" placeholder="Create password"></label></div><div class="field"><label>Phone number<input id="rPhone" value="${esc(regData.phone)}" placeholder="+91 XXXXX XXXXX"></label></div></div><div class="form-actions"><button class="outline-btn" id="regBack">← Back</button><button class="primary-btn" id="regNext">Continue →</button></div></div>`}
function profileStep(){if(regData.role==='student')return studentProfileStep();if(regData.role==='college')return collegeProfileStep();return companyProfileStep()}
function studentProfileStep(){return `<div class="reg-panel"><h1>Build your student profile</h1><p>Add the skills you know and attach certificates. Verification status is shown separately; an upload alone does not make a certificate verified.</p><div class="reg-form"><div class="field"><label>College / Institution<input id="rCollege" value="${esc(regData.college)}" placeholder="College name"></label></div><div class="field"><label>Department<input id="rDept" value="${esc(regData.department)}" placeholder="e.g. Computer Science & Engineering"></label></div><div class="field full"><label>Your skills</label><div class="skill-select"><select id="rSkill">${skills().map(s=>`<option value="${s.id}">${esc(s.name)}</option>`).join('')}</select><button class="soft-btn" id="addRegSkill">+ Add skill</button></div><div class="selected-skills">${regData.skills.map(id=>{const s=skills().find(x=>x.id===id);return `<span class="tag">${esc(s?s.name:id)} <button data-remove-skill="${id}">×</button></span>`}).join('')}</div></div><div class="field full"><label>Certificates / credentials</label><div class="upload-box"><label for="certInput"><div class="upload-icon">⇧</div><b>Drag & drop or click to upload certificates</b><p>PDF, JPG, PNG · Demo stores the file name locally</p><input id="certInput" type="file" multiple accept=".pdf,.jpg,.jpeg,.png"></label></div><div class="selected-skills">${regData.certificates.map((c,i)=>`<span class="tag">📄 ${esc(c.name)} <button data-remove-cert="${i}">×</button></span>`).join('')}</div></div></div><div class="form-actions"><button class="outline-btn" id="regBack">← Back</button><button class="primary-btn" id="createProfile">Create my profile →</button></div></div>`}
function collegeProfileStep(){return `<div class="reg-panel"><h1>Set up your college profile</h1><p>These credentials help SkillSetu establish the institution context before students and industry connect.</p><div class="reg-form"><div class="field"><label>Institution name<input id="rCollege" value="${esc(regData.college||regData.name)}" placeholder="College / University name"></label></div><div class="field"><label>Institution type<select id="rOrgType"><option>Engineering College</option><option>University</option><option>Medical / AYUSH College</option><option>Other Higher Education Institution</option></select></label></div><div class="field"><label>Official website<input id="rWebsite" value="${esc(regData.website)}" placeholder="https://institution.edu"></label></div><div class="field"><label>Location<input id="rLocation" value="${esc(regData.location)}" placeholder="City, State"></label></div><div class="field full"><label>Institution description<textarea id="rDesc" rows="3" placeholder="Briefly describe the institution">${esc(regData.description)}</textarea></label></div></div><div class="cred-box"><h4>Recommended institutional credentials</h4><ul><li>Official institution name and website/domain</li><li>Authorized admin / placement-cell contact</li><li>Affiliation or accreditation details</li><li>Institution ID / registration details where applicable</li></ul></div><div class="form-actions"><button class="outline-btn" id="regBack">← Back</button><button class="primary-btn" id="createProfile">Create college profile →</button></div></div>`}
function companyProfileStep(){return `<div class="reg-panel"><h1>Set up your company profile</h1><p>These details help students understand who is posting an opportunity and help colleges trust the organization context.</p><div class="reg-form"><div class="field"><label>Company / Organization name<input id="rCompany" value="${esc(regData.name)}" placeholder="Company name"></label></div><div class="field"><label>Organization type<select id="rOrgType"><option>Private Company</option><option>Startup</option><option>Public Sector / Government</option><option>NGO / Social Enterprise</option><option>Other</option></select></label></div><div class="field"><label>Official website<input id="rWebsite" value="${esc(regData.website)}" placeholder="https://company.com"></label></div><div class="field"><label>Head office / hiring location<input id="rLocation" value="${esc(regData.location)}" placeholder="City, State"></label></div><div class="field"><label>Authorized contact person<input id="rContact" value="${esc(regData.contactPerson||regData.name)}" placeholder="Placement / HR contact"></label></div><div class="field"><label>Company email<input value="${esc(regData.email)}" disabled></label></div><div class="field full"><label>About the organization<textarea id="rDesc" rows="3" placeholder="Brief company description">${esc(regData.description)}</textarea></label></div></div><div class="cred-box"><h4>Recommended company credentials</h4><ul><li>Official organization name and domain email</li><li>Authorized HR / recruiter contact</li><li>Company registration / legal identifier where applicable</li><li>Website and office location</li></ul></div><div class="form-actions"><button class="outline-btn" id="regBack">← Back</button><button class="primary-btn" id="createProfile">Create company profile →</button></div></div>`}

document.getElementById('registerContent').addEventListener('click',e=>{
 const roleCard=e.target.closest('[data-reg-role]');if(roleCard){regData.role=roleCard.dataset.regRole;renderRegistration();return}
 if(e.target.id==='regBack'){regStep--;renderRegistration();return}
 if(e.target.id==='regNext'){regData.name=document.getElementById('rName').value.trim();regData.email=document.getElementById('rEmail').value.trim();regData.password=document.getElementById('rPass').value;regData.phone=document.getElementById('rPhone').value.trim();if(!regData.name||!regData.email||!regData.password){toast('Please complete the required account fields.');return}regStep=3;renderRegistration();return}
 if(e.target.id==='addRegSkill'){e.preventDefault();const id=document.getElementById('rSkill').value;if(!regData.skills.includes(id))regData.skills.push(id);renderRegistration();return}
 if(e.target.dataset.removeSkill){regData.skills=regData.skills.filter(x=>x!==e.target.dataset.removeSkill);renderRegistration();return}
 if(e.target.dataset.removeCert){regData.certificates.splice(Number(e.target.dataset.removeCert),1);renderRegistration();return}
 if(e.target.id==='createProfile'){finishRegistration();return}
});
document.getElementById('registerContent').addEventListener('change',e=>{
 if(e.target.id==='certInput'){Array.from(e.target.files).forEach(f=>regData.certificates.push({name:f.name,size:f.size,status:'pending'}));renderRegistration()}
});
function readProfileFields(){
 ['rCollege','rDept','rWebsite','rLocation','rDesc','rContact','rCompany','rOrgType'].forEach(id=>{const el=document.getElementById(id);if(!el)return;const map={rCollege:'college',rDept:'department',rWebsite:'website',rLocation:'location',rDesc:'description',rContact:'contactPerson',rCompany:'name',rOrgType:'orgType'};regData[map[id]]=el.value})
}
function finishRegistration(){readProfileFields();if(regData.role==='student'&&!regData.college){toast('Add your college / institution to continue.');return}const id=regData.role[0].toUpperCase()+Date.now();const p={id,role:regData.role,name:regData.name,email:regData.email,phone:regData.phone,college:regData.college,department:regData.department,skills:regData.skills,certificates:regData.certificates,website:regData.website,location:regData.location,description:regData.description,contactPerson:regData.contactPerson,orgType:regData.orgType,createdAt:new Date().toISOString()};state.profiles[id]=p;state.account=p;state.certificates.push(...regData.certificates.map(c=>({...c,ownerId:id})));state.created=true;save();toast('Profile created successfully.');setTimeout(launchApp,350)}

/* ---------------- APP NAV ---------------- */
function navForRole(role){
 if(role==='college')return [['dashboard','▦','Dashboard'],['students','♙','Students'],['analytics','◒','Skill Analytics'],['industry','⌘','Industry Partners'],['verification','✓','Verification Center'],['reports','▤','Reports'],['settings','⚙','Settings']];
 if(role==='company')return [['dashboard','▦','Dashboard'],['post','＋','Post Opportunity'],['candidates','♙','Matching Candidates'],['analytics','◒','Talent Analytics'],['messages','◌','Messages'],['settings','⚙','Settings']];
 return [['dashboard','▦','Dashboard'],['profile','◎','My Profile'],['passport','✓','Skill Passport'],['opportunities','⌕','Opportunities'],['applications','▤','Applications'],['matching','✦','Smart Matching'],['verification','✓','Verification Center'],['assistant','✦','AI Assistant'],['settings','⚙','Settings']];
}
function launchApp(){document.getElementById('authScreen').classList.add('hidden');document.getElementById('registerScreen').classList.add('hidden');document.getElementById('appShell').classList.remove('hidden');state.currentPage='dashboard';save();renderShell();renderPage()}
function renderShell(){const p=state.account||{role:'student',name:'Demo User'};document.getElementById('sideNav').innerHTML='<div class="nav-section">Workspace</div>'+navForRole(p.role).map(n=>`<button class="nav-item ${state.currentPage===n[0]?'active':''}" data-page="${n[0]}"><span class="nav-icon">${n[1]}</span><span>${n[2]}</span></button>`).join('');document.getElementById('sideUser').innerHTML=`<span class="user-avatar">${initials(p.name)}</span><div><b>${esc(p.name)}</b><small>${esc(p.role)}</small></div>`;document.getElementById('headerAvatar').textContent=initials(p.name)}
document.getElementById('sideNav').addEventListener('click',e=>{const b=e.target.closest('[data-page]');if(!b)return;state.currentPage=b.dataset.page;save();renderShell();renderPage()});
document.getElementById('mobileMenu').onclick=()=>document.querySelector('.sidebar').classList.toggle('open');
document.getElementById('globalSearch').addEventListener('keydown',e=>{if(e.key==='Enter'){const q=e.target.value.trim().toLowerCase();if(q&&state.account.role==='student'){state.currentPage='opportunities';renderShell();renderPage();setTimeout(()=>toast(`Showing opportunity results for “${q}”`),50)}}});

function currentProfile(){return state.profiles[state.account?.id]||state.account||{role:'student',name:'Vasanth Kumar',college:'Saranathan College of Engineering',department:'Computer Science & Engineering',skills:['python','react','html','uiux','communication','teamwork'],certificates:[]}}
function studentSkills(p){const ids=p.skills||['python','react','html','uiux','communication','teamwork'];return ids.map(id=>skills().find(s=>s.id===id)||{id,name:id,cat:'Skill'})}
function pageTitle(k,sub,action=''){return `<div class="page-title"><div><span class="eyebrow">SkillSetu workspace</span><h1>${k}</h1><p>${sub}</p></div>${action}</div>`}
function renderPage(){const role=state.account?.role||'student';let html='';if(role==='student')html=studentPage(state.currentPage);else if(role==='college')html=collegePage(state.currentPage);else html=companyPage(state.currentPage);document.getElementById('pageWrap').innerHTML=html;bindPageEvents();}

/* ---------------- STUDENT PAGES ---------------- */
function studentPage(page){switch(page){case'profile':return studentProfilePage();case'passport':return passportPage();case'opportunities':return opportunitiesPage();case'applications':return applicationsPage();case'matching':return matchingPage();case'verification':return verificationPage();case'assistant':return assistantPage();case'settings':return settingsPage();default:return studentDashboard()}}
function studentDashboard(){const p=currentProfile(),ss=studentSkills(p);return pageTitle(`Good morning, ${esc((p.name||'Vasanth').split(' ')[0])} 👋`,'Your verified skills can open better opportunities. Keep your passport updated.','<button class="primary-btn" data-go="passport">View Skill Passport →</button>')+`<div class="stats"><div class="stat"><div class="stat-top"><span class="stat-icon">✓</span><span class="delta">↑ 2 this month</span></div><div class="stat-num">${Math.min(8,ss.length+2)}</div><div class="stat-label">Verified skills</div></div><div class="stat"><div class="stat-top"><span class="stat-icon">✦</span><span class="delta">↑ 12%</span></div><div class="stat-num">${ss.length+3}</div><div class="stat-label">Total skills</div></div><div class="stat"><div class="stat-top"><span class="stat-icon">▣</span><span class="delta">↑ 1 this week</span></div><div class="stat-num">3</div><div class="stat-label">Active applications</div></div><div class="stat"><div class="stat-top"><span class="stat-icon">⌁</span><span class="delta">↑ 12%</span></div><div class="stat-num">78%</div><div class="stat-label">Average match score</div></div></div><div class="grid grid-2"><div class="panel"><div class="panel-head"><h3>Recent Opportunities</h3><button class="link-btn" data-go="opportunities">View all</button></div>${jobs().slice(0,4).map(j=>opRow(j)).join('')}</div><div class="welcome-card"><h2>Your future starts here.</h2><p>Build your verified skill passport, discover matching opportunities and let colleges and companies connect around trusted skills.</p><button data-go="matching">Explore Smart Matching →</button></div></div><div class="grid grid-2" style="margin-top:14px"><div class="panel"><div class="panel-head"><h3>Skill Passport Overview</h3><button class="link-btn" data-go="passport">View passport</button></div><div class="ring-wrap"><div class="progress-ring"><b>72%</b></div><div class="legend"><div><span></span>Verified <b>8</b></div><div><span class="pending"></span>Pending <b>3</b></div><div><span style="background:#cbd7da"></span>Not verified <b>1</b></div></div></div></div><div class="panel"><div class="panel-head"><h3>Skill demand snapshot</h3><span class="eyebrow">Current</span></div>${[['React.js',92],['Python',78],['Data Analysis',65],['UI/UX Design',52]].map(x=>`<div class="bar-row"><label>${x[0]}</label><div class="bar-track"><div class="bar-fill" style="width:${x[1]}%"></div></div><strong>${x[1]}%</strong></div>`).join('')}</div></div>`}
function opRow(j){return `<div class="op-row"><div class="company-logo">${initials(j.org).slice(0,2)}</div><div class="op-main"><b>${esc(j.title)}</b><small>${esc(j.org)} · ${esc(j.loc)}</small></div><span class="match-score">${j.score||70}% Match</span><button class="apply-btn" data-apply="${j.id}">Apply</button></div>`}
function studentProfilePage(){const p=currentProfile();return pageTitle('My Profile','Your public-facing student identity on SkillSetu.','<button class="outline-btn" data-go="passport">Open Skill Passport</button>')+`<div class="profile-banner"><div class="profile-avatar">${initials(p.name)}</div><div class="profile-main"><h2>${esc(p.name)}</h2><p>Student · ${esc(p.college||'College not added')} · ${esc(p.department||'Computer Science & Engineering')}</p><span class="verified-badge">✓ Profile ready</span></div><div><small style="font-size:8px;color:#8a999f">Profile completeness</small><div class="bar-track" style="width:160px;margin-top:6px"><div class="bar-fill" style="width:85%"></div></div><small style="font-size:8px">85%</small></div></div><div class="grid grid-2"><div class="panel"><div class="panel-head"><h3>About your profile</h3><button class="link-btn" data-go="settings">Edit</button></div><div class="modal-grid"><div class="detail"><small>Email</small><b>${esc(p.email||'demo@example.com')}</b></div><div class="detail"><small>Phone</small><b>${esc(p.phone||'Not added')}</b></div><div class="detail"><small>Institution</small><b>${esc(p.college||'Not added')}</b></div><div class="detail"><small>Department</small><b>${esc(p.department||'Not added')}</b></div></div></div><div class="panel"><div class="panel-head"><h3>Profile trust</h3></div><div class="verification-note">✓ Your profile can show verification status separately from uploaded credentials. Only verified claims should be presented as verified.</div></div></div>`}
function passportPage(){const p=currentProfile(),ss=studentSkills(p);return pageTitle('Skill Passport','A portable profile of your skills, credentials and verification status.','<button class="primary-btn" data-add-skill>Add skill +</button>')+`<div class="profile-banner"><div class="profile-avatar">${initials(p.name)}</div><div class="profile-main"><h2>${esc(p.name)}</h2><p>Student · ${esc(p.college||'Saranathan College of Engineering')} · ${esc(p.department||'Computer Science & Engineering')}</p><span class="verified-badge">✓ Profile verified</span></div><div><div class="qr-box" data-qr title="SkillSetu verification record">▦</div><small style="display:block;text-align:center;font-size:7px;color:#7e8c91;margin-top:4px">Scan to verify</small></div></div><div class="panel" style="margin-bottom:14px"><div class="panel-head"><h3>Technical & professional skills</h3><span class="eyebrow">${ss.length} skills</span></div><div class="skill-grid">${ss.map((s,i)=>`<div class="skill-card"><b>${esc(s.name)}</b><small>${esc(s.cat)} · ${i<Math.ceil(ss.length*.65)?'Intermediate':'Beginner'}</small><span class="skill-status ${i>ss.length*.7?'pending':''}">${i>ss.length*.7?'Pending verification':'Verified'}</span></div>`).join('')}</div></div><div class="panel"><div class="panel-head"><h3>Certificates & credentials</h3><button class="link-btn" data-upload-cert>+ Add certificate</button></div><div class="cert-grid">${(p.certificates||[]).length? p.certificates.map(c=>`<div class="cert-card"><b>📄 ${esc(c.name)}</b><small>Uploaded credential · ${c.status==='verified'?'Verified':'Verification pending'}</small><span class="skill-status ${c.status==='verified'?'':'pending'}">${c.status==='verified'?'Verified':'Pending'}</span></div>`).join(''):'<div class="empty" style="grid-column:1/-1">No certificates added yet. Upload a credential and it will enter the verification workflow.</div>'}</div></div>`}
function opportunitiesPage(){return pageTitle('Opportunities','Discover internships and jobs ranked around your verified skills.','<button class="outline-btn">Saved jobs ♡</button>')+`<div class="filter-row"><button class="filter active">For You</button><button class="filter">Internship</button><button class="filter">Full-time</button><button class="filter">Remote</button><button class="filter">All Locations</button></div><div class="grid grid-2"><div class="panel">${jobs().map(j=>opRow(j)).join('')}</div><div class="panel"><div class="panel-head"><h3>Why these jobs?</h3></div><div class="action-card"><div class="action-icon">✓</div><div><b>Verified skills first</b><small>Matches prioritize skills that have verification status.</small></div></div><div class="action-card" style="margin-top:8px"><div class="action-icon">✦</div><div><b>Explainable score</b><small>See matched and missing skills before applying.</small></div></div><div class="action-card" style="margin-top:8px"><div class="action-icon">⌁</div><div><b>Privacy by consent</b><small>Your detailed profile is shared for a specific opportunity.</small></div></div></div></div>`}
function applicationsPage(){return pageTitle('Applications','Track where you applied and what happens next.','<button class="outline-btn">Application history</button>')+`<div class="panel"><table class="table"><thead><tr><th>Opportunity</th><th>Company</th><th>Match</th><th>Status</th></tr></thead><tbody>${jobs().slice(0,3).map((j,i)=>`<tr><td><b>${esc(j.title)}</b></td><td>${esc(j.org)}</td><td><span class="candidate-score">${j.score||70}%</span></td><td><span class="status ${i===0?'verified':'pending'}">${i===0?'Shortlisted':'Under review'}</span></td></tr>`).join('')}</tbody></table></div>`}
function matchingPage(){const p=currentProfile(),ss=studentSkills(p).map(s=>s.name);return pageTitle('Smart Matching','Understand why an opportunity fits your current verified skill profile.','<button class="primary-btn">Improve my match →</button>')+`<div class="grid grid-2"><div class="panel"><div class="panel-head"><h3>Frontend Developer Intern</h3><span class="match-score">92% Match</span></div><p style="font-size:9px;color:#718088">TechNova Solutions · Remote · 3 months</p><div class="bar-row"><label>Overall fit</label><div class="bar-track"><div class="bar-fill" style="width:92%"></div></div><strong>92%</strong></div><h4 style="font-size:10px;margin:18px 0 9px">Matched skills</h4><div class="selected-skills">${['React.js','JavaScript','HTML & CSS'].map(x=>`<span class="tag">✓ ${x}</span>`).join('')}</div><h4 style="font-size:10px;margin:18px 0 9px">Skills to improve</h4><div class="selected-skills"><span class="tag" style="background:#fff4df;color:#a76c1c">＋ Node.js</span></div></div><div class="panel"><h3 class="section-title">How the score is explained</h3><div class="action-card"><div class="action-icon">1</div><div><b>Required skills</b><small>Compare opportunity requirements against your passport.</small></div></div><div class="action-card" style="margin-top:8px"><div class="action-icon">2</div><div><b>Verification status</b><small>Verified skill claims carry trust in the matching flow.</small></div></div><div class="action-card" style="margin-top:8px"><div class="action-icon">3</div><div><b>Recommendation learning</b><small>Future ML can learn from applications and outcomes.</small></div></div></div></div>`}
function verificationPage(){const p=currentProfile();return pageTitle('Verification Center','Keep a clear record of what is uploaded, pending and verified.','<button class="primary-btn" data-upload-cert>Upload certificate</button>')+`<div class="verification-note" style="margin-bottom:14px">Important: uploading a certificate does not prove authenticity. In a production system, SkillSetu should check the issuing organization's QR, verification portal or API where available, and route exceptions to authorized institutional review.</div><div class="panel"><table class="table"><thead><tr><th>Credential</th><th>Type</th><th>Status</th><th>Action</th></tr></thead><tbody>${(p.certificates||[]).map(c=>`<tr><td><b>${esc(c.name)}</b></td><td>Certificate</td><td><span class="status ${c.status==='verified'?'verified':'pending'}">${c.status==='verified'?'Verified':'Pending'}</span></td><td><button class="link-btn" data-cert-view="${esc(c.name)}">View</button></td></tr>`).join('')||'<tr><td colspan="4" class="empty">No credentials uploaded.</td></tr>'}</tbody></table></div>`}
function assistantPage(){return pageTitle('AI Assistant','Ask SkillSetu about profiles, verification, opportunities, matching, privacy and skill development.','<span class="verified-badge">● Online</span>')+`<div class="chat-layout"><div class="chat-side"><h3>Suggested topics</h3>${['How does verification work?','Find internships for me','How is match score calculated?','What should I upload?','How is my data shared?','How can I improve my profile?'].map((x,i)=>`<div class="chat-topic ${i===0?'active':''}" data-chat-suggest="${esc(x)}">${esc(x)}</div>`).join('')}</div><div class="chat-window"><div class="chat-head"><div class="bot-avatar">✦</div><div><b>SkillSetu AI Assistant</b><small><span class="online">● Online</span> · Career & platform support</small></div></div><div id="chatLog" class="chat-log"></div><form id="chatForm" class="chat-input"><input id="chatInput" placeholder="Ask anything about SkillSetu..." required><button class="primary-btn">Send</button></form></div></div>`}
function settingsPage(){const p=currentProfile();return pageTitle('Settings','Manage your account and consent preferences.')+`<div class="grid grid-2"><div class="panel"><h3 class="section-title">Account details</h3><div class="field"><label>Name<input value="${esc(p.name)}"></label></div><div class="field"><label>Email<input value="${esc(p.email||'')}" disabled></label></div><button class="primary-btn" data-save-settings>Save changes</button></div><div class="panel"><h3 class="section-title">Privacy & sharing</h3><div class="action-card"><div class="action-icon">✓</div><div><b>Consent-based sharing</b><small>Share detailed credentials only when you choose to apply.</small></div></div><div class="action-card" style="margin-top:8px"><div class="action-icon">▣</div><div><b>Verification visibility</b><small>Show verification status separately from uploaded documents.</small></div></div></div></div>`}

