function collegeDashboard(){return pageTitle('College Dashboard','A campus-level view of student skills, verification and industry demand.','<button class="primary-btn">Export report ↓</button>')+`<div class="stats"><div class="stat"><div class="stat-icon">♙</div><div class="stat-num">1,248</div><div class="stat-label">Total students</div></div><div class="stat"><div class="stat-icon">✓</div><div class="stat-num">3,892</div><div class="stat-label">Verified skills</div></div><div class="stat"><div class="stat-icon">⌘</div><div class="stat-num">24</div><div class="stat-label">Industry partners</div></div><div class="stat"><div class="stat-icon">▣</div><div class="stat-num">186</div><div class="stat-label">Placements</div></div></div><div class="grid grid-2"><div class="panel"><div class="panel-head"><h3>Skill Gap Analysis</h3><span class="eyebrow">This semester</span></div>${[['Python',82],['React.js',69],['Java',58],['Data Science',44],['UI/UX Design',31]].map(x=>`<div class="bar-row"><label>${x[0]}</label><div class="bar-track"><div class="bar-fill" style="width:${x[1]}%"></div></div><strong>${x[1]}%</strong></div>`).join('')}</div><div class="panel"><div class="panel-head"><h3>Industry Demand</h3></div><div class="mini-chart">${[68,52,82,43,60,75].map((h,i)=>`<div><i style="height:${h}%"></i><span>${['Py','JS','React','SQL','UI','Data'][i]}</span></div>`).join('')}</div></div></div><div class="panel" style="margin-top:14px"><div class="panel-head"><h3>Recent industry activity</h3><button class="link-btn" data-page="industry">View partners</button></div>${jobs().slice(0,3).map(j=>opRow(j)).join('')}</div>`}
function collegeStudents(){return pageTitle('Students','Search student skill passports and verification status.','<button class="primary-btn">Invite students +</button>')+`<div class="panel"><table class="table"><thead><tr><th>Student</th><th>Program</th><th>Verified Skills</th><th>Profile</th></tr></thead><tbody>${['Vasanth Kumar','Ananya R.','Farhan K.','Meera S.'].map((n,i)=>`<tr><td><b>${n}</b></td><td>Computer Science & Engineering</td><td><span class="status verified">${8-i} verified</span></td><td><button class="link-btn">View passport</button></td></tr>`).join('')}</tbody></table></div>`}
function collegeAnalytics(){return pageTitle('Skill Analytics','Identify campus strengths and gaps using aggregated student and industry signals.','<button class="outline-btn">Download report</button>')+`<div class="grid grid-2"><div class="panel"><div class="panel-head"><h3>Top skills in students</h3></div>${[['Python',78],['Java',65],['Web Development',58],['Data Analysis',42],['UI/UX',28]].map(x=>`<div class="bar-row"><label>${x[0]}</label><div class="bar-track"><div class="bar-fill" style="width:${x[1]}%"></div></div><strong>${x[1]}%</strong></div>`).join('')}</div><div class="panel"><div class="panel-head"><h3>Skills demanded by industry</h3></div>${[['React.js',92],['Python',84],['SQL',76],['Cloud',62],['UI/UX',48]].map(x=>`<div class="bar-row"><label>${x[0]}</label><div class="bar-track"><div class="bar-fill" style="width:${x[1]}%"></div></div><strong>${x[1]}%</strong></div>`).join('')}</div></div>`}
function industryPage(){return pageTitle('Industry Partners','Connect curriculum and student talent with real opportunity providers.','<button class="primary-btn">Add partner +</button>')+`<div class="grid grid-3">${['TechNova Solutions','DataMind Analytics','Wellness Grove AYUSH Hospital'].map((x,i)=>`<div class="panel"><div class="company-logo">${initials(x).slice(0,2)}</div><h3 style="margin:10px 0 4px;font-size:11px">${x}</h3><p style="font-size:8px;color:#7d8b91">${i+2} active opportunities · ${12+i*8} applications</p><button class="outline-btn" style="margin-top:8px">View partnership</button></div>`).join('')}</div>`}
function collegeVerification(){return pageTitle('Verification Center','Review credentials submitted by students and maintain a trusted skill ecosystem.','<button class="outline-btn">Verification policy</button>')+`<div class="panel"><table class="table"><thead><tr><th>Student</th><th>Credential</th><th>Source</th><th>Status</th><th>Action</th></tr></thead><tbody>${['Vasanth Kumar','Ananya R.','Meera S.'].map((n,i)=>`<tr><td><b>${n}</b></td><td>${['Python Programming','Web Development','Data Analysis'][i]} Certificate</td><td>Uploaded by student</td><td><span class="status pending">Pending</span></td><td><button class="primary-btn" style="padding:6px 9px;font-size:8px">Review</button></td></tr>`).join('')}</tbody></table></div><div class="verification-note" style="margin-top:12px">Verification should use issuer QR / verification portals / APIs where available; exceptions can be routed to authorized college reviewers. Do not mark a credential verified merely because a file was uploaded.</div>`}
function reportsPage(){return pageTitle('Reports','Prepare institutional views for skill gaps, demand and outcomes.')+`<div class="grid grid-3">${[['Skill Gap Report','Students vs industry demand'],['Verification Report','Pending and verified credentials'],['Placement Readiness','Student matching and application outcomes']].map(x=>`<div class="action-card"><div class="action-icon">▤</div><div><b>${x[0]}</b><small>${x[1]}</small></div><button class="link-btn">Export</button></div>`).join('')}</div>`}

/* ---------------- COMPANY ---------------- */
function companyPage(page){switch(page){case'post':return postOpportunity();case'candidates':return candidatesPage();case'analytics':return companyAnalytics();case'messages':return messagesPage();default:return companyDashboard()}}
function companyDashboard(){return pageTitle('Company Dashboard','Find verified student talent and manage your opportunities.','<button class="primary-btn" data-page-go="post">Post new opportunity +</button>')+`<div class="stats"><div class="stat"><div class="stat-icon">▣</div><div class="stat-num">4</div><div class="stat-label">Active openings</div></div><div class="stat"><div class="stat-icon">♙</div><div class="stat-num">28</div><div class="stat-label">Total applications</div></div><div class="stat"><div class="stat-icon">✓</div><div class="stat-num">12</div><div class="stat-label">Shortlisted</div></div><div class="stat"><div class="stat-icon">★</div><div class="stat-num">3</div><div class="stat-label">Hired</div></div></div><div class="grid grid-2"><div class="panel"><div class="panel-head"><h3>Recent applications</h3><button class="link-btn" data-page-go="candidates">View all</button></div>${['Priya Sharma','Rahul Nair','Sneha Reddy'].map((n,i)=>`<div class="candidate-row"><div class="user-avatar">${initials(n)}</div><div class="op-main"><b>${n}</b><small>B.Tech CSE · ${3.8+i*.3} CGPA · ${['React.js','Python','UI/UX'][i]}</small></div><span class="candidate-score">${92-i*8}%</span><button class="outline-btn" style="padding:6px 9px;font-size:8px">View</button></div>`).join('')}</div><div class="welcome-card"><h2>Build your talent pipeline.</h2><p>Post skill requirements and let SkillSetu rank candidates around verified capabilities instead of keyword-heavy resumes.</p><button data-page-go="post">Create opportunity →</button></div></div>`}
function postOpportunity(){return pageTitle('Post an Opportunity','Tell students exactly which skills, location and experience you need.','<span class="verified-badge">✓ Company profile ready</span>')+`<div class="panel"><form id="jobPostForm"><div class="reg-form"><div class="field"><label>Job title<input id="jobTitle" required placeholder="e.g. Software Development Intern"></label></div><div class="field"><label>Job type<select id="jobType"><option>Internship</option><option>Full-time</option><option>Part-time</option></select></label></div><div class="field"><label>Location<input id="jobLocation" placeholder="Remote / City"></label></div><div class="field"><label>Experience<select id="jobExp"><option>0–1 year</option><option>1–2 years</option><option>2+ years</option></select></label></div><div class="field full"><label>Required skills</label><div class="selected-skills" id="jobSkillTags">${['Python','React.js','JavaScript','SQL'].map(x=>`<span class="tag">${x} ×</span>`).join('')}</div></div><div class="field full"><label>Minimum qualification<textarea id="jobQual" rows="2" placeholder="B.E / B.Tech / relevant degree"></textarea></label></div></div><div class="form-actions"><span style="font-size:9px;color:#87959a">Candidates will see the skill requirements and match explanation.</span><button class="primary-btn">Post opportunity →</button></div></form></div>`}
function candidatesPage(){return pageTitle('Matching Candidates','Ranked candidates based on required skills and verification status.','<button class="outline-btn">Export shortlist ↓</button>')+`<div class="filter-row"><button class="filter active">All candidates</button><button class="filter">90%+ Match</button><button class="filter">Verified skills</button><button class="filter">Recent</button></div><div class="panel">${['Priya Sharma','Rahul Nair','Sneha Reddy','Arjun Kumar'].map((n,i)=>`<div class="candidate-row"><div class="user-avatar">${initials(n)}</div><div class="op-main"><b>${n}</b><small>${['Saranathan College of Engineering','Anna University','NIT Trichy','PSG Tech'][i]} · B.Tech CSE</small><div class="selected-skills"><span class="tag">✓ React.js</span><span class="tag">✓ Python</span><span class="tag" style="background:#fff4df;color:#a76c1c">SQL</span></div></div><div style="text-align:right"><div class="candidate-score">${92-i*8}%</div><small style="font-size:7px;color:#839197">match score</small></div><button class="outline-btn">View</button></div>`).join('')}</div>`}
function companyAnalytics(){return pageTitle('Talent Analytics','See which skills are available and where your hiring gaps are.')+`<div class="grid grid-2"><div class="panel"><div class="panel-head"><h3>Skills requested in your openings</h3></div>${[['React.js',86],['Python',72],['JavaScript',68],['SQL',55],['UI/UX',32]].map(x=>`<div class="bar-row"><label>${x[0]}</label><div class="bar-track"><div class="bar-fill" style="width:${x[1]}%"></div></div><strong>${x[1]}%</strong></div>`).join('')}</div><div class="panel"><div class="panel-head"><h3>Hiring funnel</h3></div><div class="mini-chart">${[100,72,46,28,14].map((h,i)=>`<div><i style="height:${h}%"></i><span>${['Views','Apply','Match','Shortlist','Hire'][i]}</span></div>`).join('')}</div></div></div>`}
function messagesPage(){return pageTitle('Messages','Coordinate with shortlisted candidates and institutional partners.')+`<div class="panel">${['Priya Sharma','Saranathan College Placement Cell','Rahul Nair'].map((n,i)=>`<div class="candidate-row"><div class="user-avatar">${initials(n)}</div><div class="op-main"><b>${n}</b><small>${['Thanks for reviewing my application.','New student cohort is ready for your opening.','I have added my latest certificate.'][i]}</small></div><span style="font-size:8px;color:#8b989e">${i+1}h ago</span></div>`).join('')}</div>`}

/* ---------------- COMMON EVENTS ---------------- */
function bindPageEvents(){
 document.querySelectorAll('[data-go]').forEach(b=>b.addEventListener('click',()=>{state.currentPage=b.dataset.go;renderShell();renderPage()}));
 document.querySelectorAll('[data-page-go]').forEach(b=>b.addEventListener('click',()=>{state.currentPage=b.dataset.pageGo;renderShell();renderPage()}));
 document.querySelectorAll('[data-apply]').forEach(b=>b.addEventListener('click',()=>toast('Application saved — your verified profile will be shared for this opportunity.')));
 const form=document.getElementById('chatForm');if(form){initChat();form.addEventListener('submit',e=>{e.preventDefault();const i=document.getElementById('chatInput');sendChat(i.value);i.value=''})}
 document.querySelectorAll('[data-chat-suggest]').forEach(b=>b.onclick=()=>sendChat(b.dataset.chatSuggest));
 document.querySelectorAll('[data-qr]').forEach(b=>b.onclick=()=>showModal(`<button class="modal-close" onclick="closeModal()">×</button><h2>SkillSetu Verification QR</h2><p>This demo QR represents a SkillSetu verification record. In production, a scanned code should open a server-side verification record and show the current verification status.</p><div class="qr-box" style="margin:15px auto;width:150px;height:150px;font-size:70px">▦</div><div class="verification-note">Do not treat a SkillSetu-generated QR as proof that the original certificate is authentic unless the underlying issuer verification has been completed.</div>`));
 document.querySelectorAll('[data-upload-cert]').forEach(b=>b.onclick=()=>uploadCertificateModal());
 const jobForm=document.getElementById('jobPostForm');if(jobForm)jobForm.addEventListener('submit',e=>{e.preventDefault();toast('Opportunity posted successfully. Matching candidates are now available.');state.currentPage='candidates';save();setTimeout(()=>{renderShell();renderPage()},500)});
 const saveSet=document.querySelector('[data-save-settings]');if(saveSet)saveSet.onclick=()=>toast('Profile settings saved.');
}
function uploadCertificateModal(){showModal(`<button class="modal-close" onclick="closeModal()">×</button><h2>Add a certificate</h2><p>Upload a credential to your profile. It will start as <b>Pending verification</b> until an authorized verification path confirms it.</p><div class="upload-box"><label for="modalCert"><div class="upload-icon">⇧</div><b>Click to choose a certificate</b><p>PDF, JPG, PNG</p><input id="modalCert" type="file" accept=".pdf,.jpg,.jpeg,.png"></label></div><div class="modal-actions"><button class="outline-btn" onclick="closeModal()">Cancel</button></div>`);document.getElementById('modalCert').onchange=e=>{const f=e.target.files[0];if(!f)return;const p=currentProfile();p.certificates=p.certificates||[];p.certificates.push({name:f.name,size:f.size,status:'pending'});state.profiles[p.id]=p;save();closeModal();toast('Certificate uploaded and marked Pending verification.');renderPage()}}

/* ---------------- SMART CHATBOT ---------------- */
function initChat(){const log=document.getElementById('chatLog');if(!log)return;log.innerHTML='';addChat('Hi! I’m SkillSetu AI Assistant. I can explain verification, matching, profiles, certificates, privacy, internships and skill gaps. What would you like to know?','bot')}
function addChat(text,who){const log=document.getElementById('chatLog');if(!log)return;const d=document.createElement('div');d.className='chat-msg '+who;d.textContent=text;log.appendChild(d);log.scrollTop=log.scrollHeight}
function sendChat(message){const m=(message||'').trim();if(!m)return;addChat(m,'user');setTimeout(()=>addChat(chatReply(m),'bot'),250)}
function chatReply(raw){const m=raw.toLowerCase(),p=currentProfile();const ss=studentSkills(p).map(s=>s.name);const has=x=>m.includes(x);if(has('hello')||has('hi')||has('hey'))return `Hi ${p.name?.split(' ')[0]||'there'}! I can help you with SkillSetu, from registration and certificates to matching and privacy.`;if(has('verify')||has('verification')||has('genuine')||has('fake'))return 'Verification is a separate trust step. A student uploads a credential, then SkillSetu should check the issuer’s QR, official verification portal or API where available. If no digital source exists, the claim can remain pending for authorized institutional review. Uploading a file alone does not make it verified.';if(has('qr')||has('scan'))return 'There are two QR concepts: an issuer QR, when the certificate provider has one, and a SkillSetu QR for a successfully recorded verification. SkillSetu should never create a QR and claim that it proves an original certificate is authentic.';if(has('intern')||has('job')||has('opportun')||has('apply'))return `Based on the demo profile, strong opportunity areas include Frontend Development, Data Analytics and UI/UX. Your current profile includes ${ss.slice(0,5).join(', ')}. Open Opportunities to see the requirements and apply.`;if(has('match')||has('score'))return 'A match score compares the skills required by an opportunity with the student’s profile. In the current prototype, the explanation shows matched and missing skills; verified claims should carry more trust. A future ML model can improve recommendations after enough application, selection and feedback data is collected.';if(has('skill gap')||has('demand')||has('industry'))return 'SkillSetu can aggregate job requirements to show colleges and administrators which skills are in demand. Colleges can compare that demand with student skill profiles and identify training gaps.';if(has('certificate')||has('upload'))return 'For a student, the onboarding flow asks for known skills and certificate uploads. Certificates begin as Pending verification; later, the verification workflow can use issuer records or authorized college review.';if(has('profile')||has('register')||has('account'))return 'There are three role-based registration flows: Student, College and Company. Students add institution, department, skills and certificates; colleges add institutional identity and authorized contact details; companies add organization identity, website, location and hiring contact.';if(has('privacy')||has('data')||has('security')||has('share'))return 'SkillSetu should use consent-based sharing, role-based access, limited data collection, secure verification records and audit logs. A student’s detailed information should not be automatically shared with every company.';if(has('college'))return 'The College workspace focuses on student management, verification review, skill-gap analytics, industry partnerships and reports.';if(has('company')||has('employer')||has('recruit'))return 'The Company workspace lets an organization create its profile, post opportunities with required skills, view explainable candidate matches and manage its hiring pipeline.';if(has('ml')||has('ai'))return 'The prototype uses explainable rule-based matching for reliability. The planned AI/ML layer can learn from historical skills, requirements, applications, shortlists, selections and employer/student feedback once enough quality data is available.';if(has('how')||has('work')||has('flow'))return 'The core flow is: choose Student, College or Company → create account → complete role-specific profile → verify relevant credentials → discover or publish opportunities → match skills → apply, shortlist or collaborate.';return 'I can help with verification, certificates, skill matching, internships, privacy, student/college/company profiles, skill-demand analytics or the future ML layer. Try asking a specific question, such as “How does certificate verification work?”'}

/* direct-file demo logout */
document.addEventListener('keydown',e=>{if(e.key==='Escape')closeModal()});

(async()=>{await bootData();if(state.account&&state.created){launchApp()}else{openLogin()}})();
